
-- OTROS SERVICIOS
		
		
INSERT INTO rips_ripsotrosservicios ("codPrestador", "numAutorizacion", "idMIPRES", "fechaSuministroTecnologia" , "tipoOS_id", 
	"codTecnologiaSalud_id",   "numDocumentoIdentificacion", "vrServicio",	"valorPagoModerador", "numFEVPagoModerador", consecutivo, "fechaRegistro", "codComplicacion_id", "codDiagnosticoPrincipal_id","codDiagnosticoRelacionado_id", "codProcedimiento_id", "codServicio_id", "conceptoRecaudo_id", "finalidadTecnologiaSalud_id",	"grupoServicios_id", "modalidadGrupoServicioTecSal_id", "tipoDocumentoIdentificacion_id","usuarioRegistro_id", "viaIngresoServicioSalud_id", "ripsDetalle_id", "itemFactura", "ripsTipos_id", "tipoPagoModerador_id", "ripsTransaccion_id", "estadoReg" , ingreso_id)  SELECT sed."codigoHabilitacion", facdet."fecha", null mipres, null numeroAutorizacion,usu.documento,facdet."valorTotal",' +  str(proRata)  + ', fac.id, row_number() OVER(ORDER BY facdet.id) AS consecutivo, now(), null,diag1.id,diag2.id,	exa.id, serv.id, ' + str('5')  + ', 	final.id, gru.id, mod.id, tipdocrips.id, ' +  str(username_id) + ', ingreso.id, detrips.id, facdet."consecutivoFactura", ' +  str('4')  + ', (select max(ripsmoderadora.id) from cartera_pagos pagos, cartera_formaspagos formapago, rips_ripstipospagomoderador ripsmoderadora where  i."tipoDoc_id" =  pagos."tipoDoc_id" and i.documento_id = pagos.documento_id and i.consec = pagos.consec and pagos."formaPago_id" = formapago.id and ripsmoderadora."codigoAplicativo" = cast(formapago.id as text)),' + str(transaccionId) + ",'A','"  + str(ingresoId.id) + "'"  + ' FROM sitios_sedesclinica sed inner join facturacion_facturacion fac ON (fac."sedesClinica_id" = sed.id)  inner join  facturacion_facturaciondetalle facdet ON (facdet.facturacion_id = fac.id and facdet."examen_id" is not null and (facdet.anulado = ' + "'" + str('N')  + "'" +  ' or facdet.anulado = ' + "'" + str('R') + "')" + ' and ' + '"tipoRegistro" = ' + "'" + str('MANUAL') + "')" +  ' inner join clinico_examenes exa ON (exa.id = facdet."examen_id" )    inner  join admisiones_ingresos i on (i."tipoDoc_id" = fac."tipoDoc_id" and i.documento_id = fac.documento_id and i.consec = fac."consecAdmision") left join rips_ripsviasingresosalud ingreso ON (ingreso.id = i."ripsViaIngresoServicioSalud_id") inner  join rips_ripsenvios e ON (e."sedesClinica_id" = sed.id) inner join rips_ripsdetalle detrips ON (detrips."ripsEnvios_id" = e.id and detrips."numeroFactura_id" = fac.id) left join rips_ripsmodalidadatencion  mod ON (mod.id = i."ripsmodalidadGrupoServicioTecSal_id") left join rips_ripsgruposervicios gru ON (gru.id = i."ripsGrupoServicios_id")    left join rips_ripsServicios serv ON (serv.id = i."ripsGrupoServicios_id")  left join rips_ripsfinalidadconsulta final on (final.id = i."ripsFinalidadConsulta_id")  inner join usuarios_tiposdocumento tipdoc ON (tipdoc.id = fac."tipoDoc_id" ) left join rips_ripstiposdocumento tipdocrips on (tipdocrips.id = tipdoc."tipoDocRips_id" ) inner join usuarios_usuarios usu ON (usu."tipoDoc_id" = fac."tipoDoc_id" and usu.id = fac.documento_id ) left join clinico_diagnosticos diag1 on (diag1.id=i."dxActual_id") left join clinico_diagnosticos diag2 on (diag2.id= i."dxIngreso_id")  where sed.id = ' + "'" + str(sede) + "'" + ' and e.id = ' + "'" + str(envioRipsId) + "'" + ' and fac.id = ' + "'" + str(elemento) + "' and facdet.examen_id is not null"
 